package org.sleepwell.app;
import android.content.Context;import javax.net.ssl.SSLException;import java.net.*;import java.util.concurrent.*;
/** Explicit settings actions survive rotation without retaining an Activity or replaying a request. */
final class HueBridgeWork {
 enum Kind{LOAD,PAIR,LIGHTS,CHECK,TEST,SAVE,DISCONNECT}
 private static final ExecutorService WORKER=Executors.newSingleThreadExecutor(r->new Thread(r,"SleepWell Hue settings"));
 static final class Operation{final Kind kind;final HueBridgeConfig input;volatile boolean done,cancelled;volatile String issue="",notice="";volatile HueBridgeConfig result;volatile HueBridgeApi.Lights lights;volatile HueBridgeApi api;Operation(Kind kind,HueBridgeConfig input){this.kind=kind;this.input=input;}void cancel(){if(kind==Kind.SAVE||kind==Kind.DISCONNECT)return;cancelled=true;HueBridgeApi owned=api;if(owned!=null)owned.close();}}
 static Operation start(Context context,Kind kind,HueBridgeConfig input){Context app=context.getApplicationContext();Operation op=new Operation(kind,input);WORKER.execute(()->{try{if(op.cancelled)return;if(kind==Kind.LOAD){op.result=HueBridgeSettings.load(app);return;}if(HueBridgeSettings.prefs(app).getLong("revision",0)!=input.revision)throw new IllegalStateException("Saved Hue settings changed. Reopen before continuing.");if(kind==Kind.TEST){HueBridgeConfig saved=HueBridgeSettings.load(app);if(!same(saved,input))throw new IllegalStateException("Save the complete selected bridge/light/settings draft before testing it.");op.result=saved;return;}if(kind==Kind.SAVE){op.result=HueBridgeSettings.save(app,input);op.notice="Hue settings saved. No lamp was changed. The next real alarm may use this selection if enabled.";return;}if(kind==Kind.DISCONNECT){HueBridgeSettings.disconnect(app,input.revision);op.result=HueBridgeConfig.empty().revision(input.revision+1);op.notice="Disconnected locally. The bridge app user is not revoked automatically; manage it in the official Hue app.";return;}try(HueBridgeApi api=new HueBridgeApi(input,()->!op.cancelled&&HueBridgeSettings.prefs(app).getLong("revision",0)==input.revision)){op.api=api;if(kind==Kind.PAIR){String key=api.pair();op.result=new HueBridgeConfig(input.address,input.identity,input.pin,key,"","",false,input.minutes,input.maximum,input.restore,input.revision);op.notice="A bridge app user was created. Load lights, explicitly choose one, then Save. Closing without Save does not revoke that bridge user.";}else if(kind==Kind.LIGHTS){op.lights=api.lights();op.notice=op.lights.lights.size()+" selectable dimmable light(s) · "+op.lights.unsupported+" unsupported or unavailable resource(s). No lamp was changed.";}else{HueBridgeApi.State state=api.read();op.notice="Read-only check: chosen light is "+(state.on?"on":"off")+" · stored brightness "+Math.round(state.brightness*100f/254)+"%. No lamp was changed.";}}if(op.cancelled)op.notice="Bridge operation cancelled. An already submitted pairing request cannot be recalled.";
 }catch(Exception failure){if(op.cancelled)op.issue="Bridge operation cancelled. An already submitted pairing request cannot be recalled.";else if(failure instanceof SSLException||failure instanceof java.security.cert.CertificateException)op.issue="TLS refused. Independently verify the certificate fingerprint, bridge identity, certificate dates and firmware. No HTTP fallback was attempted.";else if(failure instanceof java.net.SocketTimeoutException)op.issue="The selected bridge timed out. Confirm the same LAN and its manual IPv4 address.";else if(failure instanceof IllegalArgumentException||failure instanceof IllegalStateException)op.issue=failure.getMessage()==null?"Hue configuration is unavailable.":failure.getMessage();else op.issue="The selected bridge could not complete this bounded HTTPS/v1 operation. Check its connection, pairing and firmware support.";}finally{op.api=null;op.done=true;}});return op;}
 private static boolean same(HueBridgeConfig a,HueBridgeConfig b){return a.revision==b.revision&&a.destination().equals(b.destination())&&a.key.equals(b.key)&&a.light.equals(b.light)&&a.enabled==b.enabled&&a.minutes==b.minutes&&a.maximum==b.maximum&&a.restore==b.restore;}
 private HueBridgeWork(){}
}
